('1057eb71-b5ea-5bd5-b262-1d568cfa7315', '07c257db-1c4d-5809-bfd2-d9c67f0064bb'::uuid, 'malick.mbengue@demo.ept-alumni.invalid', 'Hello les EPT de Ziguinchor, Kaolack et Mbour ! On a créé ce groupe pour ceux qui travaillent hors de Dakar.', date_trunc('day', now()) - interval '30 days' + interval '1237 minutes', false, false),
