) as v(id, conversation, email, contenu, envoye, systeme, supprime)
join utilisateur u on u.email = v.email
join conversations c on c.id = v.conversation
on conflict do nothing;
update conversations c set dernier_message_le = m.dernier
from (select conversation_id, max(envoye_le) as dernier from messages group by conversation_id) m
where m.conversation_id = c.id and m.dernier > c.dernier_message_le;
commit;
